def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'

    opp_coops = 0
    for h in history:
        if h[1] == 'C':
            opp_coops += 1
    opp_rate = opp_coops / n

    last_opp = history[-1][1]
    last_me = history[-1][0]

    dd_streak = 0
    for h in reversed(history):
        if h[0] == 'D' and h[1] == 'D':
            dd_streak += 1
        else:
            break

    if dd_streak >= 3:
        return 'C'

    if opp_rate > 0.85:
        if n > 90:
            return 'D'
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    if opp_rate < 0.3:
        return 'D'

    if last_opp == 'D':
        if opp_rate > 0.6 and rng.random() < 0.4:
            return 'C'
        return 'D'
    else:
        if last_me == 'D' and rng.random() < 0.9:
            return 'C'
        return 'C'
